// ES6 class (syntactic sugar over prototypes)
class Animal {
  constructor(name) { this.name = name; }
  speak() { return `${this.name} makes a sound`; }
}

class Dog extends Animal {
  speak() { return `${this.name} barks`; }
}

const rex = new Dog('Rex');
console.log(rex.speak());          // Rex barks
console.log(rex instanceof Dog);   // true
console.log(Object.getPrototypeOf(rex) === Dog.prototype); // true

// The equivalent pre-ES6 prototype style
function AnimalOld(name) { this.name = name; }
AnimalOld.prototype.speak = function () { return `${this.name} makes a sound`; };

function DogOld(name) { AnimalOld.call(this, name); }   // inherit instance fields
DogOld.prototype = Object.create(AnimalOld.prototype);  // inherit methods
DogOld.prototype.constructor = DogOld;
DogOld.prototype.speak = function () { return `${this.name} barks`; };

const rexOld = new DogOld('Rex');
console.log(rexOld.speak()); // Rex barks
```
- Classes are NOT a new object model: `class Dog {}` creates a function whose `prototype` object holds the methods, and instances link to it via their internal `[[Prototype]]`.
- `extends` sets up the prototype chain plus `super()` handling; `Object.create` is the manual equivalent in the old style.
- Differences: class declarations are not usable before their definition (no hoisting for them), class bodies always run in strict mode, and class methods are non-enumerable.

```javascript
// تابع async برای دریافت داده‌ها از API
async function fetchData() {
  try {
    // استفاده از await برای صبر کردن برای دریافت پاسخ
    const response = await fetch('https://jsonplaceholder.typicode.com/posts/1');

    // بررسی موفقیت‌آمیز بودن درخواست
    if (!response.ok) {
      throw new Error(`خطا در دریافت داده: ${response.status}`);
    }

    // تبدیل پاسخ به JSON
    const data = await response.json();

    // نمایش داده‌ها در کنسول
    console.log('داده‌های دریافت شده:', data);
    return data;
  } catch (error) {
    // مدیریت خطاها
    console.error('خطا:', error);
  }
}

// فراخوانی تابع
fetchData();
```

در این مثال، ما یک تابع async به نام fetchData ایجاد کردیم. با استفاده از کلیدواژه async، تابع ما قادر است از await استفاده کند. await باعث می‌شود اجرای تابع تا زمان دریافت پاسخ از fetch متوقف شود. 

try/catch برای مدیریت خطاها استفاده شده است. اگر درخواست موفقیت‌آمیز نباشد، خطای مناسب نمایش داده می‌شود. response.ok وضعیت پاسخ را بررسی می‌کند و response.json() داده‌های دریافتی را به فرمت JSON تبدیل می‌کند.

این روش خوانایی کد را به شدت افزایش می‌دهد و از callback hell جلوگیری می‌کند. async/await بهترین راه برای کار با عملیات غیرهمزمان در جاوااسکریپت مدرن است.

async functions always return a promise; await pauses the function (not the page) until it settles. Always pair awaits with try/catch or .catch — a rejected promise without handling becomes an unhandled rejection.

```js
async function load() {
  try {
    const res = await fetch("/api/items");
    if (!res.ok) throw new Error(res.status);
    return await res.json();
  } catch (err) {
    console.error("load failed:", err);
    return [];
  }
}
```

