```javascript
// تابع async برای دریافت داده‌ها از API
async function fetchUserData(userId) {
  try {
    // استفاده از await برای صبر کردن پاسخ API
    const response = await fetch(`https://jsonplaceholder.typicode.com/users/${userId}`);

    // بررسی موفقیت‌آمیز بودن درخواست
    if (!response.ok) {
      throw new Error(`خطا در دریافت داده‌ها: ${response.status}`);
    }

    // تبدیل پاسخ به JSON
    const userData = await response.json();

    // نمایش داده‌های کاربر
    console.log('نام کاربر:', userData.name);
    console.log('ایمیل کاربر:', userData.email);

    return userData;
  } catch (error) {
    console.error('خطا:', error);
    return null;
  }
}

// فراخوانی تابع با شناسه کاربر 1
fetchUserData(1);
```

در این مثال، ما از تابع `async` برای تعریف تابعی استفاده کرده‌ایم که به صورت غیرهمزمان اجرا می‌شود. کلیدواژه `await` باعث می‌شود که اجرای تابع تا زمان دریافت پاسخ از API متوقف شود. این روش خوانایی کد را به شدت افزایش می‌دهد و مدیریت خطا را با استفاده از بلوک `try-catch` آسان‌تر می‌کند.

نکته مهم: `fetch` به صورت پیش‌فرض خطاهای شبکه‌ای را به عنوان خطا در نظر نمی‌گیرد، بنابراین ما باید وضعیت پاسخ را با `response.ok` بررسی کنیم. این روش در مقایسه با استفاده از Promise.then() ساختار کد را خطی‌تر و قابل فهم‌تر می‌کند.

