```js
const form = document.querySelector('#profile');

form.addEventListener('submit', async e => {
  e.preventDefault();
  const fd = new FormData(form);        // collects ALL named fields

  console.log(fd.get('name'));          // 'Sara'
  console.log(fd.get('newsletter'));    // 'on' — absent entirely when unchecked
  console.log(fd.get('avatar'));        // a File object

  fd.append('meta', JSON.stringify({ source: 'web' })); // extra fields are fine

  // multipart/form-data header is set AUTOMATICALLY — never set Content-Type yourself
  const res = await fetch('/api/profile', { method: 'POST', body: fd });
  if (!res.ok) throw new Error(`Upload failed: ${res.status}`);
});

// Building FormData programmatically / converting
const fd2 = new FormData();
fd2.set('page', '1');
console.log(Object.fromEntries(fd2));  // snapshot as object (loses duplicate keys)
console.log([...fd2.entries()]);       // full list including duplicates and files
// For plain (non-file) forms: new URLSearchParams(fd2) gives x-www-form-urlencoded
```
`new FormData(form)` reads every field that has a `name`, including `File` inputs. Gotchas: unchecked checkboxes are simply missing (check with `fd.has()`), and when sending FormData via fetch the browser sets the multipart boundary header itself — manually setting `Content-Type` breaks uploads.

```html
<!DOCTYPE html>
<html lang="fa">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>مثال Fetch با Async/Await</title>
    <style>
        body { font-family: Tahoma, sans-serif; direction: rtl; }
        #data-container { margin: 20px; padding: 15px; border: 1px solid #ccc; }
        .loading { color: #666; }
        .error { color: red; }
    </style>
</head>
<body>
    <h1>داده‌های API</h1>
    <button id="load-data">بارگذاری داده‌ها</button>
    <div id="data-container"></div>

    <script>
        const loadButton = document.getElementById('load-data');
        const dataContainer = document.getElementById('data-container');

        // تابع اصلی با async/await
        async function fetchData() {
            dataContainer.innerHTML = '<p class="loading">در حال بارگذاری...</p>';

            try {
                // استفاده از fetch برای دریافت داده‌ها
                const response = await fetch('https://jsonplaceholder.typicode.com/posts/1');

                // بررسی موفقیت‌آمیز بودن درخواست
                if (!response.ok) {
                    throw new Error(`خطا: ${response.status}`);
                }

                // تبدیل پاسخ به JSON
                const data = await response.json();

                // نمایش داده‌ها
                dataContainer.innerHTML = `
                    <h2>${data.title}</h2>
                    <p>${data.body}</p>
                `;
            } catch (error) {
                // مدیریت خطاها
                dataContainer.innerHTML = `<p class="error">خطا در دریافت داده‌ها: ${error.message}</p>`;
            }
        }

        // افزودن رویداد کلیک به دکمه
        loadButton.addEventListener('click', fetchData);
    </script>
</body>
</html>
```

در این مثال، ما از ترکیب `async/await` با `fetch` برای دریافت داده‌ها از یک API استفاده کردیم. کلیدواژه `async` تابع را به صورت promises-based اجرا می‌کند و `await` منتظر می‌ماند تا عملیات `fetch` کامل شود. استفاده از `try/catch` مدیریت خطاها را آسان می‌کند. مزیت اصلی این روش خوانایی بالای کد است، زیرا ساختار کد شبیه به کد سنکرون می‌شود اما به صورت ناهمزمان اجرا می‌گردد. ابتدا وضعیت loading نمایش داده می‌شود، سپس در صورت موفقیت، داده‌ها نمایش داده می‌شوند و در صورت خطا، پیام خطا نمایش داده می‌شود.

