```js
const bar = document.getElementById('progress');
addEventListener('scroll', () => {
  const max = document.documentElement.scrollHeight - innerHeight;
  bar.style.width = (scrollY / max) * 100 + '%';
}, { passive: true });

document.getElementById('copy').addEventListener('click', async e => {
  const code = document.querySelector('pre code').textContent;
  await navigator.clipboard.writeText(code);
  e.target.textContent = 'Copied!';
  setTimeout(() => (e.target.textContent = 'Copy code'), 1500);
});
```

Why it works: the progress bar maps scrollY to a percentage of the scrollable height on a passive listener, and the Clipboard API writes plain text from textContent so HTML entities like &gt; come out as the real characters.

```javascript
// تابع async برای دریافت داده‌ها از API
async function getUserData(userId) {
  try {
    // استفاده از await برای صبر کردن تا پاسخ API برگردد
    const response = await fetch(`https://jsonplaceholder.typicode.com/users/${userId}`);

    // بررسی موفقیت‌آمیز بودن درخواست
    if (!response.ok) {
      throw new Error(`خطا در دریافت داده‌ها: ${response.status}`);
    }

    // تبدیل پاسخ به JSON
    const userData = await response.json();

    // نمایش داده‌های دریافت شده
    console.log('نام کاربر:', userData.name);
    console.log('ایمیل کاربر:', userData.email);

    return userData;
  } catch (error) {
    // مدیریت خطاها
    console.error('خطا:', error);
    return null;
  }
}

// فراخوانی تابع
getUserData(1);
```

در این مثال، ما از تابع async برای تعریف یک تابع استفاده می‌کنیم که به ما اجازه می‌دهد از await برای مدیریت عملیات غیرهمزمان استفاده کنیم. ابتدا درخواست API با ارسال userId ارسال می‌شود. سپس منتظر می‌مانیم تا پاسخ دریافت شود. اگر پاسخ موفقیت‌آمیز بود، داده‌ها به JSON تبدیل می‌شوند و در کنسول نمایش داده می‌شوند. اگر خطایی رخ دهد، در بخش catch مدیریت می‌شود. استفاده از async/await کد را خواناتر و قابل فهم‌تر می‌کند و از callback hell جلوگیری می‌کند.

